import {AMENITIES} from './planning.js';
import {capacity,interval,quote,addDays,whatsappNumber} from './model.js';

export function whatsappHref(number,message){const digits=whatsappNumber(number);return digits?`https://wa.me/${digits}?text=${encodeURIComponent(message)}`:null}
export function enquiryText({language='hr',apartment='',arrival='',departure='',adults=2,children=0,name='',message=''}={}){
 const words={hr:['Pozdrav! Zanima me boravak u apartmanima Meleh.','Apartman','Po dogovoru','Dolazak','Odlazak','Datumi po dogovoru','Odrasli','Djeca','Ime','Molim vas potvrdu dostupnosti i ponudu.'],en:['Hello! I am interested in a stay at Meleh Apartments.','Apartment','Any apartment','Check-in','Check-out','Dates to be arranged','Adults','Children','Name','Please confirm availability and send me an offer.'],de:['Hallo! Ich interessiere mich für einen Aufenthalt in den Meleh Apartments.','Apartment','Nach Vereinbarung','Anreise','Abreise','Reisedaten nach Vereinbarung','Erwachsene','Kinder','Name','Bitte bestätigen Sie die Verfügbarkeit und senden Sie mir ein Angebot.']}[language]||null;
 const w=words||['Pozdrav! Zanima me boravak u apartmanima Meleh.','Apartman','Po dogovoru','Dolazak','Odlazak','Datumi po dogovoru','Odrasli','Djeca','Ime','Molim vas potvrdu dostupnosti i ponudu.'];
 return [w[0],'',`${w[1]}: ${apartment||w[2]}`,...(interval(arrival,departure)?[`${w[3]}: ${arrival}`,`${w[4]}: ${departure}`]:[w[5]]),`${w[6]}: ${adults}`,`${w[7]}: ${children}`,...(name.trim()?[`${w[8]}: ${name.trim()}`]:[]),...(message.trim()?['',message.trim()]:[]),'',w[9]].join('\n');
}
export function stayIssue(data,apartments,today){
 if((data.arrival||data.departure)&&(!interval(data.arrival,data.departure)||data.arrival<today))return 'dates';
 const adults=Number(data.adults),children=Number(data.children||0);
 if(!Number.isInteger(adults)||adults<1||adults>40||!Number.isInteger(children)||children<0||children>40)return 'guests';
 const a=apartments.find(a=>a.slug===data.apartment);
 return a&&adults+children>capacity(a)?'capacity':null;
}

export function createStayTools({S,t,esc,url,photo,getLang,navigate}){
 const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
 const money=n=>new Intl.NumberFormat({hr:'hr-HR',en:'en-GB',de:'de-DE'}[getLang()],{style:'currency',currency:'EUR'}).format(n);
 const title=()=>t('Usporedite apartmane.','Compare apartments.','Apartments vergleichen.');
 const waNote=()=>t('Poruku možete pregledati i urediti u WhatsAppu. Šaljete je sami; upit nije rezervacija.','Review and edit the message in WhatsApp. You send it yourself; an enquiry is not a booking.','Sie können die Nachricht in WhatsApp prüfen und bearbeiten. Sie versenden sie selbst; eine Anfrage ist keine Buchung.');
 function cardLink(a){return `<a class="compare-link" href="/usporedba/?apartments=${encodeURIComponent([a.slug,...S.apartments.filter(x=>x.slug!==a.slug).slice(0,2).map(x=>x.slug)].join(','))}">${t('Usporedi apartmane','Compare apartments','Apartments vergleichen')} ⇄</a>`}
 function waLink(data={},label='WhatsApp',extra=''){const a=S.apartments.find(a=>a.slug===data.apartment),href=whatsappHref(S.whatsapp,enquiryText({...data,apartment:a?.name||'',language:getLang()}));return href?`<a class="btn outline whatsapp-link" ${extra} href="${esc(href)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:''}
 function contactPanel(){return `<section class="whatsapp-panel"><h3>${t('Radije putem WhatsAppa?','Prefer WhatsApp?','Lieber per WhatsApp?')}</h3>${whatsappNumber(S.whatsapp)?`<p>${t('Podaci iz obrasca pripremaju poruku. Za ovaj način upita ime i e-mail nisu obavezni.','The form details prepare your message. Your name and email are optional for this enquiry method.','Die Angaben im Formular bereiten Ihre Nachricht vor. Name und E-Mail sind dafür optional.')}</p><details><summary>${t('Pregled poruke','Message preview','Nachrichtenvorschau')}</summary><pre id="whatsapp-preview"></pre></details>${waLink({},t('Otvori WhatsApp','Open WhatsApp','WhatsApp öffnen'),'id="whatsapp-contact"')}<p id="whatsapp-error" class="form-error" role="alert"></p><p class="section-note">${waNote()}</p>`:`<p>${t('WhatsApp će biti dostupan nakon što domaćin unese kontaktni broj. Upit zasad možete pripremiti putem obrasca.','WhatsApp will be available once the host adds a contact number. You can prepare an enquiry using the form.','WhatsApp ist verfügbar, sobald der Gastgeber eine Kontaktnummer hinterlegt. Bereiten Sie Ihre Anfrage über das Formular vor.')}</p>`}</section>`}
 function comparisonPage(){
 const query=new URLSearchParams(location.search),requested=query.has('apartments')?query.get('apartments').split(','):S.apartments.slice(0,3).map(a=>a.slug),selected=S.apartments.filter(a=>requested.includes(a.slug)).slice(0,3);
 const bounded=(value,fallback,min)=>Number.isInteger(Number(value))&&Number(value)>=min&&Number(value)<=40?Number(value):fallback;
 const arrival=query.get('arrival')||'',departure=query.get('departure')||'',adults=bounded(query.get('adults')??2,2,1),children=bounded(query.get('children')??0,0,0);
 const valid=interval(arrival,departure)&&arrival>=today(),guestCount=Math.max(1,adults)+Math.max(0,children);
 return `<section class="page-head"><div class="wrap"><div class="breadcrumbs"><a href="/">${t('Naslovnica','Home','Startseite')}</a> / ${t('Usporedba','Comparison','Vergleich')}</div><h1>${title()}</h1><p>${t('Odaberite do tri apartmana i pronađite prostor koji vam najbolje odgovara.','Choose up to three apartments and find the space that suits you best.','Wählen Sie bis zu drei Apartments und finden Sie Ihren Lieblingsplatz.')}</p></div></section><section class="section"><div class="wrap"><form id="compare-form" class="compare-controls"><fieldset><legend>${t('Apartmani za usporedbu · najviše 3','Apartments to compare · up to 3','Apartments vergleichen · maximal 3')}</legend><div class="compare-choices">${S.apartments.map(a=>`<label><input type="checkbox" name="apartments" value="${esc(a.slug)}" ${selected.includes(a)?'checked':''}>${esc(a.name)}</label>`).join('')}</div></fieldset><div class="form-grid"><label class="field">${t('Dolazak (nije obavezno)','Check-in (optional)','Anreise (optional)')}<input name="arrival" type="date" min="${today()}" value="${esc(valid?arrival:'')}"></label><label class="field">${t('Odlazak (nije obavezno)','Check-out (optional)','Abreise (optional)')}<input name="departure" type="date" min="${esc(valid?addDays(arrival,1):today())}" value="${esc(valid?departure:'')}"></label><label class="field">${t('Odrasli','Adults','Erwachsene')}<input name="adults" type="number" min="1" max="40" required value="${Math.min(40,Math.max(1,adults))}"></label><label class="field">${t('Djeca','Children','Kinder')}<input name="children" type="number" min="0" max="40" value="${Math.min(40,Math.max(0,children))}"></label></div><button class="btn" type="submit">${t('Prikaži usporedbu','Show comparison','Vergleich anzeigen')} ⇄</button><p id="compare-error" class="form-error" role="alert"></p><p id="compare-edit-note" class="section-note" hidden>${t('Primijenite novi odabir gumbom „Prikaži usporedbu”.','Apply your new selection with “Show comparison”.','Übernehmen Sie Ihre Auswahl mit „Vergleich anzeigen“.')}</p></form><p class="section-note">${S.demo?t('Ogledni podaci i fotografije. Cijene i sadržaje potvrđuje domaćin.','Illustrative details and photos. Prices and facilities are confirmed by the host.','Beispielangaben und Fotos. Preise und Ausstattung bestätigt der Gastgeber.'):t('Konačnu cijenu, dostupnost i eventualne dodatne troškove potvrđuje domaćin.','The host confirms final prices, availability and any additional charges.','Endpreise, Verfügbarkeit und mögliche Zusatzkosten bestätigt der Gastgeber.')}</p><div id="compare-results" class="comparison-grid">${selected.map(a=>{const q=valid?quote(a,arrival,departure):null,tooMany=guestCount>capacity(a),params=new URLSearchParams({apartman:a.slug,adults:String(Math.min(40,Math.max(1,adults))),children:String(Math.min(40,Math.max(0,children))),...(valid?{arrival,departure}:{})});const rows=[[t('Kapacitet','Capacity','Kapazität'),`${a.guests} ${t('osobe','guests','Personen')}`],[t('Spavaće sobe','Bedrooms','Schlafzimmer'),a.rooms],[t('Kupaonice','Bathrooms','Badezimmer'),a.baths],[t('Površina','Floor area','Wohnfläche'),a.area+' m²'],[t('Kat','Floor','Etage'),a.floor||t('Na upit','On request','Auf Anfrage')],...Object.entries(AMENITIES).map(([k,l])=>[l[{hr:0,en:1,de:2}[getLang()]],a.amenities?.[k]===true?t('Da','Yes','Ja'):a.amenities?.[k]===false?t('Ne','No','Nein'):t('Nepotvrđeno','Unconfirmed','Unbestätigt')])];return `<article class="comparison-card">${photo(a.image)}<div class="comparison-body"><h2>${esc(a.name)}</h2><dl>${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="comparison-price"><span>${valid?t('Smještaj za odabrani boravak','Accommodation for your stay','Unterkunft für Ihren Aufenthalt'):t('Cijena boravka','Stay price','Aufenthaltspreis')}</span><strong>${q?money(q.total):t('Na upit','On request','Auf Anfrage')}</strong><p>${q?`${q.nights} ${t('noći','nights','Nächte')} · ${t('Minimalno','Minimum','Mindestens')} ${q.minNights} ${t(q.minNights===1?'noć':'noći',q.minNights===1?'night':'nights',q.minNights===1?'Nacht':'Nächte')}`:valid?t('Za ove datume još nema potpunog cjenika.','A complete price list is not available for these dates.','Für diese Reisedaten liegt noch keine vollständige Preisliste vor.'):t('Dodajte datume za izračun prema cjeniku.','Add dates for a calculation from the price list.','Reisedaten für eine Berechnung laut Preisliste ergänzen.')}</p>${q&&!q.meetsMinimum?`<p class="compare-warning">${t('Odabrani boravak kraći je od minimalnog.','Your stay is shorter than the minimum.','Ihr Aufenthalt ist kürzer als der Mindestaufenthalt.')}</p>`:''}</div>${tooMany?`<p class="compare-warning">${t('Premalen kapacitet za odabrani broj gostiju.','Insufficient capacity for your guest count.','Nicht genügend Platz für die gewählte Gästezahl.')}</p>`:`<a class="btn" href="/kontakt/?${esc(params)}">${t('Pripremi upit','Prepare enquiry','Anfrage vorbereiten')} ↗</a>${waLink({apartment:a.slug,arrival:valid?arrival:'',departure:valid?departure:'',adults,children})}`}<a class="text-link" href="${url(a.slug)}">${t('Detalji apartmana','Apartment details','Apartmentdetails')} ↗</a></div></article>`}).join('')}</div></div></section>`;
 }
 function bind(){const form=document.querySelector('#compare-form');if(form){form.oninput=()=>{document.querySelector('#compare-results').hidden=true;document.querySelector('#compare-edit-note').hidden=false};form.arrival.onchange=()=>{form.departure.min=form.arrival.value?addDays(form.arrival.value,1):today()};form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form)),slugs=new FormData(form).getAll('apartments'),error=document.querySelector('#compare-error');if(!slugs.length||slugs.length>3){error.textContent=t('Odaberite između jednog i tri apartmana.','Choose between one and three apartments.','Wählen Sie ein bis drei Apartments.');return}if(stayIssue(data,[],today())){error.textContent=t('Provjerite datume i broj gostiju.','Check your dates and guest count.','Prüfen Sie Reisedaten und Gästezahl.');return}const params=new URLSearchParams({apartments:slugs.join(','),adults:data.adults,children:data.children||'0',...(data.arrival?{arrival:data.arrival,departure:data.departure}:{})});navigate('/usporedba/?'+params)}}
 const inquiry=document.querySelector('#inquiry'),link=document.querySelector('#whatsapp-contact');if(inquiry&&link){const links=[link,...document.querySelectorAll('.mobile-contact .whatsapp-link')];const update=()=>{const data=Object.fromEntries(new FormData(inquiry)),a=S.apartments.find(a=>a.slug===data.apartment),text=enquiryText({...data,apartment:a?.name||'',language:getLang()});document.querySelector('#whatsapp-preview').textContent=text;links.forEach(a=>a.href=whatsappHref(S.whatsapp,text));document.querySelector('#whatsapp-error').textContent=''};inquiry.addEventListener('input',update);inquiry.addEventListener('change',update);inquiry.addEventListener('reset',()=>requestAnimationFrame(update));update();links.forEach(a=>a.onclick=e=>{const issue=stayIssue(Object.fromEntries(new FormData(inquiry)),S.apartments,today());if(issue){e.preventDefault();document.querySelector('#whatsapp-error').textContent=issue==='capacity'?t('Broj gostiju prelazi kapacitet apartmana.','Guest count exceeds the apartment capacity.','Die Gästezahl übersteigt die Apartmentkapazität.'):t('Provjerite datume i broj gostiju u obrascu.','Check the dates and guest count in the form.','Prüfen Sie Reisedaten und Gästezahl im Formular.')}})}}
 return {comparisonPage,cardLink,waLink,contactPanel,bind};
}
